import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2018-07-11 Ceph Developer Monthly","description":"","frontmatter":{"title":"2018-07-11 Ceph Developer Monthly","date":"2018-07-11T00:00:00.000Z","updated":"2018-07-19T00:00:00.000Z","tags":["Ceph","分布式存储","SOFI Fest Shell","Backfill 优化","健康检查"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-07-11_Ceph_Developer_Monthly.md","filePath":"posts/2018/2018-07-11_Ceph_Developer_Monthly.md","lastUpdated":1780460162000}'),o={name:"posts/2018/2018-07-11_Ceph_Developer_Monthly.md"};function n(r,l,p,a,g,_){return t(),i("div",null,[...l[0]||(l[0]=[s("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年某月某日</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： Pavani（实习生）、Lonnie、Josh、VG等</p><p><strong>会议主题</strong>：</p><ol><li><strong>SOFI Fest Shell演示</strong>： Pavani介绍了她开发的SOFI Fest Shell，这是一个简化访问文件系统的工具，用户可以通过脚本执行简单操作，无需手动挂载。与会人员对SOFI Fest Shell的功能表示赞赏，并提出了改进建议，例如支持命令行执行、匹配参数顺序等。</li><li><strong>Backfill优化</strong>： 讨论了针对快速设备进行Backfill优化的问题，提出了使用布隆过滤器、Merkle树等技术方案，以减少数据传输量和计算量。</li><li><strong>健康检查历史记录</strong>： 讨论了将健康检查历史记录发布到Insights的问题，并提出了使用订阅功能和结构化日志等解决方案。</li></ol><p><strong>会议详情</strong>：</p><ol><li><strong>SOFI Fest Shell演示</strong>： <ul><li>Pavani介绍了SOFI Fest Shell的功能，包括文件列表、目录树复制、自动完成、系统命令等。</li><li>与会人员对SOFI Fest Shell的功能表示赞赏，并提出了改进建议，例如支持命令行执行、匹配参数顺序等。</li></ul></li><li><strong>Backfill优化</strong>： <ul><li>讨论了Backfill优化的问题，特别是针对快速设备时的效率问题。</li><li>提出了使用布隆过滤器、Merkle树等技术方案，以减少数据传输量和计算量。</li><li>讨论了布隆过滤器的实现细节，包括时间窗口、内存占用等。</li><li>讨论了Merkle树的实现细节，包括数据结构、版本控制等。</li><li>讨论了其他优化方案，例如并行处理、增量更新等。</li></ul></li><li><strong>健康检查历史记录</strong>： <ul><li>讨论了将健康检查历史记录发布到Insights的问题，并提出了使用订阅功能和结构化日志等解决方案。</li><li>讨论了健康检查历史记录的格式和内容。</li><li>讨论了如何将健康检查历史记录与SNMP模块等模块进行整合。</li></ul></li></ol><p><strong>后续行动计划</strong>：</p><ol><li><strong>SOFI Fest Shell</strong>： <ul><li>Pavani将继续完善SOFI Fest Shell，并根据反馈进行改进。</li><li>与会人员将测试SOFI Fest Shell，并提出反馈意见。</li></ul></li><li><strong>Backfill优化</strong>： <ul><li>与会人员将研究布隆过滤器和Merkle树等技术方案，并评估其可行性。</li><li>与会人员将讨论并行处理和增量更新等优化方案。</li></ul></li><li><strong>健康检查历史记录</strong>： <ul><li>与会人员将研究订阅功能和结构化日志等解决方案，并评估其可行性。</li><li>与会人员将讨论如何将健康检查历史记录与SNMP模块等模块进行整合。</li></ul></li></ol><p><strong>关键词</strong>：</p><ul><li>SOFI Fest Shell</li><li>Backfill</li><li>布隆过滤器</li><li>Merkle树</li><li>健康检查</li><li>Insights</li><li>SNMP模块</li></ul>",12)])])}const F=e(o,[["render",n]]);export{S as __pageData,F as default};
